import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Link, useLocation, useNavigate } from "@tanstack/react-router";
import {
  Activity, AlertTriangle, Bell, Bot, Boxes, ChevronDown, ChevronRight, CircleHelp, Clock3,
  Cloud, Code2, Database, Gauge, GitBranch, Globe2, HeartPulse, KeyRound, LayoutDashboard,
  LifeBuoy, ListFilter, LockKeyhole, Menu, Network, PanelLeftClose, PanelRight, Play, Plus,
  Radio, RefreshCw, Search, Server, Settings, ShieldCheck, Star, Trash2, Users, Workflow, X,
  type LucideIcon,
} from "lucide-react";
import { Background, Controls, Handle, MiniMap, Position, ReactFlow, type Edge, type Node, type NodeProps } from "@xyflow/react";
import { memo, useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Switch } from "@/components/ui/switch";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { api, ApiError, readToken, saveToken, type Dashboard, type DataSource, type MapNode, type MonitorTemplate, type Snapshot, type TopologyMap } from "@/lib/api";
import { createDemoSnapshot } from "@/lib/demo-data";
import { extensionManifest, type ExtensionCategory, type ExtensionManifest } from "@/lib/extensions";
import { cn } from "@/lib/utils";

type NavItem = { label: string; path: string; icon: LucideIcon; favorite?: boolean };
type NavGroup = { label: string; items: NavItem[] };

const navGroups: NavGroup[] = [
  { label: "Início", items: [["Visão geral", "", LayoutDashboard, true], ["Prioridades agora", "prioridades", AlertTriangle, true], ["Saúde do ambiente", "saude", HeartPulse]].map(toNav) },
  { label: "Aplicações / APM", items: [["Aplicações", "aplicacoes", Boxes], ["Serviços", "servicos", Server, true], ["Service Mapping", "service-mapping", Workflow, true], ["Dependências", "dependencias", GitBranch], ["Traces", "traces", Activity], ["Requisições", "requisicoes", Radio], ["Erros & exceções", "erros", AlertTriangle], ["SLOs", "slos", Gauge]].map(toNav) },
  { label: "Infraestrutura", items: [["Hosts", "hosts", Server, true], ["Processos", "processos", Activity], ["Containers", "containers", Boxes], ["Kubernetes/OpenShift", "kubernetes", Cloud], ["Network Mapping", "network-mapping", Network, true], ["Dispositivos de rede", "dispositivos-rede", Globe2], ["Interfaces", "interfaces", Radio]].map(toNav) },
  { label: "Monitoramento", items: [["Templates", "templates", ListFilter, true], ["Descobertas", "descobertas", Search], ["Itens & métricas", "itens-metricas", Gauge], ["Alertas", "alertas", Bell], ["Incidentes", "incidentes", AlertTriangle, true], ["Regras de correlação", "correlacao", GitBranch]].map(toNav) },
  { label: "Explorar", items: [["Data Sources", "data-sources", Database, true], ["Logs", "logs", ListFilter], ["Métricas", "metricas", Activity], ["Consultas", "consultas", Code2]].map(toNav) },
  { label: "Visualização", items: [["Dashboards", "dashboards", LayoutDashboard, true], ["Editor de painéis", "editor-paineis", PanelRight], ["HTML Graphics", "html-graphics", Code2], ["Modo TV", "modo-tv", Play]].map(toNav) },
  { label: "Automação", items: [["IA & RCA", "ia-rca", Bot], ["MCP Hub", "mcp-hub", Bot], ["Integrações", "integracoes", Workflow], ["Webhooks", "webhooks", Radio]].map(toNav) },
  { label: "Extensões", items: [["Hub de Extensões", "extensoes", Boxes, true], ["Minhas extensões", "minhas-extensoes", Star]].map(toNav) },
  { label: "Administração", items: [["Usuários & acesso", "usuarios-acesso", Users, true], ["Autenticação (SSO/MFA)", "autenticacao", ShieldCheck], ["Chaves de API", "chaves-api", KeyRound], ["Agentes", "agentes", Radio], ["Configurações", "configuracoes", Settings], ["Auditoria", "auditoria", ListFilter], ["Ajuda", "ajuda", CircleHelp]].map(toNav) },
];

function toNav(tuple: [string, string, LucideIcon, boolean?]): NavItem { return { label: tuple[0], path: tuple[1], icon: tuple[2], favorite: tuple[3] }; }
const labels = new Map(navGroups.flatMap((group) => group.items.map((item) => [item.path, item.label])));

function routePath(path: string) { return path ? `/${path}` : "/"; }
function useCurrentPath() { return useLocation({ select: (location) => location.pathname.replace(/^\//, "").replace(/\/$/, "") }); }

export function ObservaApp() {
  const queryClient = useQueryClient();
  const path = useCurrentPath();
  const [mobileNav, setMobileNav] = useState(false);
  const [collapsed, setCollapsed] = useState(false);
  const [navSearch, setNavSearch] = useState("");
  const [globalSearch, setGlobalSearch] = useState("");
  const [demo, setDemo] = useState(false);
  const [hydrated, setHydrated] = useState(false);
  const [polling, setPolling] = useState(30_000);

  useEffect(() => { setHydrated(true); }, []);
  const snapshotQuery = useQuery({ queryKey: ["snapshot", demo], queryFn: () => demo ? Promise.resolve(createDemoSnapshot()) : api.snapshot(), enabled: hydrated, retry: false, refetchInterval: demo ? false : polling });
  const unauthorized = snapshotQuery.error instanceof ApiError && snapshotQuery.error.status === 401;
  const unreachable = snapshotQuery.error instanceof ApiError && snapshotQuery.error.status !== 401;

  function enterDemo() { setDemo(true); void queryClient.invalidateQueries({ queryKey: ["snapshot"] }); }
  function exitDemo() { setDemo(false); void queryClient.invalidateQueries({ queryKey: ["snapshot"] }); }

  return (
    <div className="min-h-screen bg-background text-foreground">
      {demo && <DemoBanner onExit={exitDemo} />}
      <div className={cn("flex min-h-screen", demo && "pt-9")}>
        <aside className={cn("fixed inset-y-0 left-0 z-40 hidden border-r border-sidebar-border bg-sidebar transition-[width] duration-200 md:flex md:flex-col", demo && "top-9", collapsed ? "w-16" : "w-[248px]")}>
          <SidebarNav collapsed={collapsed} search={navSearch} setSearch={setNavSearch} current={path} />
        </aside>
        <div className={cn("min-w-0 flex-1 transition-[margin] duration-200", collapsed ? "md:ml-16" : "md:ml-[248px]")}>
          <Topbar current={path} collapsed={collapsed} onCollapse={() => setCollapsed((value) => !value)} onMobile={() => setMobileNav(true)} search={globalSearch} setSearch={setGlobalSearch} polling={polling} setPolling={setPolling} onRefresh={() => void snapshotQuery.refetch()} isRefreshing={snapshotQuery.isFetching} />
          <main className="min-h-[calc(100vh-56px)] p-4 lg:p-6 xl:p-7">
            {!hydrated || snapshotQuery.isLoading ? <LoadingState /> : snapshotQuery.data ? <PageRouter path={path} snapshot={snapshotQuery.data} demo={demo} globalSearch={globalSearch} /> : <ConnectionGate unauthorized={unauthorized} unreachable={unreachable} error={snapshotQuery.error} onDemo={enterDemo} onRetry={() => void snapshotQuery.refetch()} />}
          </main>
        </div>
      </div>
      <Sheet open={mobileNav} onOpenChange={setMobileNav}>
        <SheetContent side="left" className="w-[88vw] max-w-[320px] border-sidebar-border bg-sidebar p-0">
          <SheetHeader className="sr-only"><SheetTitle>Navegação</SheetTitle><SheetDescription>Menu principal</SheetDescription></SheetHeader>
          <SidebarNav collapsed={false} search={navSearch} setSearch={setNavSearch} current={path} onNavigate={() => setMobileNav(false)} />
        </SheetContent>
      </Sheet>
    </div>
  );
}

function DemoBanner({ onExit }: { onExit: () => void }) {
  return <div className="fixed inset-x-0 top-0 z-[60] flex h-9 items-center justify-center gap-3 bg-demo px-3 text-xs font-semibold text-demo-foreground"><span className="rounded-sm border border-current px-1.5 py-0.5 text-[10px]">DEMO</span><span className="truncate">Dados ilustrativos — nenhuma telemetria real está sendo exibida.</span><Button variant="ghost" size="sm" className="h-7 text-demo-foreground hover:bg-demo-foreground/10" onClick={onExit}>Sair</Button></div>;
}

function SidebarNav({ collapsed, search, setSearch, current, onNavigate }: { collapsed: boolean; search: string; setSearch: (value: string) => void; current: string; onNavigate?: () => void }) {
  const filtered = navGroups.map((group) => ({ ...group, items: group.items.filter((item) => item.label.toLowerCase().includes(search.toLowerCase())) })).filter((group) => group.items.length);
  return <>
    <div className="flex h-16 shrink-0 items-center gap-3 border-b border-sidebar-border px-4">
      <div className="grid size-8 shrink-0 place-items-center rounded-md bg-primary text-primary-foreground"><Activity className="size-5" /></div>
      {!collapsed && <div><div className="font-semibold leading-tight">Observa Lite</div><div className="text-[10px] font-medium uppercase text-muted-foreground">Linux Observability</div></div>}
    </div>
    {!collapsed && <div className="p-3"><div className="relative"><Search className="absolute left-2.5 top-2.5 size-4 text-muted-foreground" /><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Filtrar navegação" className="h-9 border-sidebar-border bg-sidebar-accent pl-8 text-xs" /></div></div>}
    <nav className="observa-scrollbar flex-1 overflow-y-auto px-2 pb-4">
      {filtered.map((group) => <div key={group.label} className="mt-3">
        {!collapsed && <div className="px-2 pb-1.5 text-[10px] font-semibold uppercase text-nav-section">{group.label}</div>}
        <div className="space-y-0.5">{group.items.map((item) => <NavLink key={item.path || "home"} item={item} active={current === item.path} collapsed={collapsed} onNavigate={onNavigate} />)}</div>
      </div>)}
    </nav>
    <div className="border-t border-sidebar-border p-2"><div className={cn("flex items-center gap-2 rounded-md bg-sidebar-accent p-2", collapsed && "justify-center")}><span className="relative flex size-2"><span className="absolute inline-flex size-full animate-ping rounded-full bg-success opacity-40" /><span className="relative inline-flex size-2 rounded-full bg-success" /></span>{!collapsed && <span className="text-xs text-muted-foreground">Interface pronta para o servidor</span>}</div></div>
  </>;
}

function NavLink({ item, active, collapsed, onNavigate }: { item: NavItem; active: boolean; collapsed: boolean; onNavigate?: () => void }) {
  const content = <Link to="/$" params={{ _splat: item.path }} onClick={onNavigate} className={cn("group flex h-9 items-center gap-2.5 rounded-md px-2.5 text-[13px] text-sidebar-foreground transition-colors hover:bg-sidebar-accent hover:text-foreground", active && "bg-sidebar-accent text-primary", collapsed && "justify-center px-0")}><item.icon className="size-4 shrink-0" />{!collapsed && <><span className="min-w-0 flex-1 truncate">{item.label}</span>{item.favorite && <Star className="size-3 fill-current opacity-0 group-hover:opacity-60" />}</>}</Link>;
  return collapsed ? <Tooltip><TooltipTrigger asChild>{content}</TooltipTrigger><TooltipContent side="right">{item.label}</TooltipContent></Tooltip> : content;
}

function Topbar({ current, collapsed, onCollapse, onMobile, search, setSearch, polling, setPolling, onRefresh, isRefreshing }: { current: string; collapsed: boolean; onCollapse: () => void; onMobile: () => void; search: string; setSearch: (v: string) => void; polling: number; setPolling: (v: number) => void; onRefresh: () => void; isRefreshing: boolean }) {
  return <header className="sticky top-0 z-30 flex h-14 items-center gap-2 border-b border-border bg-background/95 px-3 backdrop-blur lg:px-5">
    <Button variant="ghost" size="icon" className="md:hidden" onClick={onMobile} aria-label="Abrir menu"><Menu /></Button>
    <Button variant="ghost" size="icon" className="hidden md:inline-flex" onClick={onCollapse} aria-label={collapsed ? "Expandir menu" : "Recolher menu"}><PanelLeftClose className={cn("transition-transform", collapsed && "rotate-180")} /></Button>
    <div className="hidden items-center gap-1 text-xs text-muted-foreground lg:flex"><span>Observa Lite</span><ChevronRight className="size-3" /><span className="font-medium text-foreground">{labels.get(current) ?? "Visão geral"}</span></div>
    <div className="mx-auto hidden w-full max-w-md md:block"><div className="relative"><Search className="absolute left-3 top-2.5 size-4 text-muted-foreground" /><Input value={search} onChange={(event) => setSearch(event.target.value)} className="h-9 bg-surface pl-9 text-xs" placeholder="Pesquisar host, serviço, PID ou evento" /></div></div>
    <Select defaultValue="producao"><SelectTrigger className="hidden h-8 w-[126px] bg-surface text-xs xl:flex"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="producao">Produção</SelectItem><SelectItem value="homologacao">Homologação</SelectItem></SelectContent></Select>
    <Select value={String(polling)} onValueChange={(value) => setPolling(Number(value))}><SelectTrigger className="hidden h-8 w-[114px] bg-surface text-xs lg:flex"><Clock3 className="size-3" /><SelectValue /></SelectTrigger><SelectContent><SelectItem value="15000">15 s</SelectItem><SelectItem value="30000">30 s</SelectItem><SelectItem value="60000">1 min</SelectItem><SelectItem value="0">Manual</SelectItem></SelectContent></Select>
    <Button variant="ghost" size="icon" className="size-8" onClick={onRefresh} aria-label="Atualizar"><RefreshCw className={cn(isRefreshing && "animate-spin")} /></Button>
    <Button variant="ghost" size="icon" className="relative size-8" aria-label="Notificações"><Bell /><span className="absolute right-1.5 top-1.5 size-1.5 rounded-full bg-danger" /></Button>
    <div className="flex size-8 shrink-0 items-center justify-center rounded-full border border-border bg-surface text-[11px] font-semibold">OP</div>
  </header>;
}

function ConnectionGate({ unauthorized, unreachable, error, onDemo, onRetry }: { unauthorized: boolean; unreachable: boolean; error: unknown; onDemo: () => void; onRetry: () => void }) {
  const queryClient = useQueryClient();
  const [token, setToken] = useState("");
  const hasToken = readToken().length > 0;
  function submit(event: FormEvent) { event.preventDefault(); saveToken(token.trim()); setToken(""); void queryClient.invalidateQueries({ queryKey: ["snapshot"] }); }
  return <div className="mx-auto flex min-h-[70vh] max-w-5xl items-center justify-center"><div className="grid w-full overflow-hidden rounded-lg border border-border bg-surface lg:grid-cols-[1.05fr_.95fr]">
    <div className="border-b border-border p-7 lg:border-b-0 lg:border-r lg:p-10"><div className="mb-6 grid size-11 place-items-center rounded-md bg-primary text-primary-foreground"><LockKeyhole /></div><h1 className="text-2xl font-semibold">Conectar ao Observa Lite</h1><p className="mt-2 max-w-md text-sm leading-6 text-muted-foreground">Informe o token de administração do servidor existente. Ele ficará somente nesta aba e será enviado no cabeçalho das chamadas REST.</p><div className="mt-5 inline-flex items-center gap-2 rounded-md border border-warning/30 bg-warning/10 px-3 py-2 text-xs text-warning"><KeyRound className="size-4" /> Acesso por token (modo inicial)</div>
      <form onSubmit={submit} className="mt-7 space-y-3"><Label htmlFor="api-token">Token da API</Label><Input id="api-token" type="password" autoComplete="off" value={token} onChange={(event) => setToken(event.target.value)} placeholder="Cole o token do servidor" required /><div className="flex flex-wrap gap-2"><Button type="submit">Conectar</Button>{hasToken && <Button variant="outline" type="button" onClick={() => { saveToken(""); onRetry(); }}>Remover token</Button>}</div></form>
      {unauthorized && <p className="mt-4 text-xs text-danger">O servidor respondeu 401. Confira o token e tente novamente.</p>}
    </div>
    <div className="flex flex-col justify-between bg-surface-raised p-7 lg:p-10"><div><div className="text-xs font-semibold uppercase text-muted-foreground">Estado da conexão</div><div className="mt-4 flex items-start gap-3"><span className={cn("mt-1 size-2 rounded-full", unauthorized ? "bg-danger" : "bg-warning")} /><div><div className="font-medium">{unauthorized ? "Autorização necessária" : unreachable ? "Servidor não alcançável" : "Conexão pendente"}</div><p className="mt-1 text-sm text-muted-foreground">{error instanceof Error ? error.message : "Verifique o endereço e a disponibilidade do backend Go."}</p></div></div></div><div className="mt-10 border-t border-border pt-6"><p className="text-sm font-medium">Precisa avaliar a interface sem backend?</p><p className="mt-1 text-xs leading-5 text-muted-foreground">O modo demonstração usa dados ilustrativos e mantém uma faixa visível em todas as páginas.</p><Button variant="outline" className="mt-4" onClick={onDemo}>Entrar no modo demonstração</Button></div></div>
  </div></div>;
}

function LoadingState() { return <div className="space-y-5"><div className="h-8 w-64 animate-pulse rounded bg-muted" /><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[1,2,3,4].map((i) => <div key={i} className="h-28 animate-pulse rounded-lg border border-border bg-surface" />)}</div><div className="h-[480px] animate-pulse rounded-lg border border-border bg-surface" /></div>; }

function PageRouter({ path, snapshot, demo, globalSearch }: { path: string; snapshot: Snapshot; demo: boolean; globalSearch: string }) {
  if (["service-mapping", "network-mapping"].includes(path)) return <MappingView kind={path === "service-mapping" ? "service" : "network"} map={path === "service-mapping" ? snapshot.service_map : snapshot.network_map} demo={demo} />;
  if (path === "extensoes" || path === "minhas-extensoes") return <ExtensionHub configuredOnly={path === "minhas-extensoes"} />;
  if (path === "usuarios-acesso" || path === "autenticacao" || path === "chaves-api") return <AuthSettings section={path} />;
  if (path === "templates") return <TemplateEditor items={snapshot.templates} demo={demo} />;
  if (path === "data-sources") return <DataSourceEditor items={snapshot.datasources} demo={demo} />;
  if (["dashboards", "editor-paineis", "html-graphics"].includes(path)) return <DashboardBuilder items={snapshot.dashboards} demo={demo} />;
  if (["incidentes", "prioridades", "alertas", "erros"].includes(path)) return <IncidentList events={snapshot.events} />;
  if (path === "servicos" || path === "aplicacoes") return <ServicesPage snapshot={snapshot} filter={globalSearch} />;
  if (path === "hosts" || path === "processos" || path === "containers" || path === "kubernetes") return <InfrastructurePage snapshot={snapshot} path={path} />;
  if (!path || path === "saude") return <Overview snapshot={snapshot} demo={demo} />;
  return <FuturePage title={labels.get(path) ?? "Área operacional"} />;
}

function PageHeader({ eyebrow, title, description, actions }: { eyebrow?: string; title: string; description: string; actions?: ReactNode }) { return <div className="mb-6 flex flex-col justify-between gap-4 lg:flex-row lg:items-end"><div>{eyebrow && <div className="mb-1 text-[11px] font-semibold uppercase text-primary">{eyebrow}</div>}<h1 className="text-2xl font-semibold tracking-normal">{title}</h1><p className="mt-1 max-w-3xl text-sm text-muted-foreground">{description}</p></div>{actions && <div className="flex shrink-0 gap-2">{actions}</div>}</div>; }
function KPIStats({ items }: { items: Array<{ label: string; value: string | number; detail: string; tone?: string; icon: LucideIcon }> }) { return <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{items.map((item) => <div key={item.label} className="rounded-lg border border-border bg-surface p-4"><div className="flex items-center justify-between"><span className="text-xs font-medium text-muted-foreground">{item.label}</span><item.icon className={cn("size-4", item.tone ?? "text-primary")} /></div><div className="mt-3 text-2xl font-semibold tabular-nums">{item.value}</div><div className="mt-1 text-xs text-muted-foreground">{item.detail}</div></div>)}</div>; }

function Overview({ snapshot, demo }: { snapshot: Snapshot; demo: boolean }) {
  const services = snapshot.service_map.nodes.length; const issues = snapshot.events.filter((event) => event.status !== "resolvido").length;
  return <><PageHeader eyebrow="Visão geral" title="Saúde do ambiente" description="Estado consolidado da telemetria Linux, dependências e eventos recentes." actions={<span className="flex items-center gap-2 text-xs text-muted-foreground"><span className="size-2 rounded-full bg-success" />{demo ? "Amostra demonstrativa" : `Gerado ${formatDate(snapshot.generated_at)}`}</span>} /><KPIStats items={[{ label: "Hosts observados", value: snapshot.hosts.length, detail: "Com inventário recente", icon: Server }, { label: "Serviços mapeados", value: services, detail: `${snapshot.service_map.edges.length} dependências`, icon: Workflow }, { label: "Prioridades abertas", value: issues, detail: "Requerem análise", icon: AlertTriangle, tone: issues ? "text-warning" : "text-success" }, { label: "Monitores ativos", value: snapshot.templates.filter((item) => item.enabled).length, detail: `${snapshot.templates.length} templates configurados`, icon: HeartPulse }]}/>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.45fr_.75fr]"><section className="rounded-lg border border-border bg-surface"><SectionTitle title="Prioridades agora" subtitle="Eventos ordenados por impacto operacional" link="/incidentes" />{snapshot.events.length ? <IncidentRows events={snapshot.events.slice(0, 5)} /> : <EmptyState icon={ShieldCheck} title="Nenhuma prioridade aberta" description="Eventos do backend aparecerão aqui quando forem detectados." />}</section><section className="rounded-lg border border-border bg-surface"><SectionTitle title="Inventário recente" subtitle="Últimos hosts observados" />{snapshot.hosts.length ? snapshot.hosts.slice(0, 5).map((host) => <div key={host.id} className="flex items-center gap-3 border-t border-border px-4 py-3"><div className="grid size-8 place-items-center rounded bg-muted"><Server className="size-4" /></div><div className="min-w-0 flex-1"><div className="truncate text-sm font-medium">{host.name}</div><div className="truncate text-xs text-muted-foreground">{host.os} · {host.addresses.join(", ")}</div></div><span className="size-2 rounded-full bg-success" /></div>) : <EmptyState icon={Server} title="Sem hosts" description="Instale ou conecte um agente para começar a descoberta." />}</section></div>
  </>;
}

function SectionTitle({ title, subtitle, link }: { title: string; subtitle: string; link?: string }) { return <div className="flex items-center justify-between p-4"><div><h2 className="text-sm font-semibold">{title}</h2><p className="mt-0.5 text-xs text-muted-foreground">{subtitle}</p></div>{link && <Link to="/$" params={{ _splat: link.replace(/^\//, "") }} className="text-xs font-medium text-primary hover:underline">Ver tudo</Link>}</div>; }
function EmptyState({ icon: Icon, title, description }: { icon: LucideIcon; title: string; description: string }) { return <div className="flex min-h-52 flex-col items-center justify-center p-8 text-center"><div className="grid size-11 place-items-center rounded-lg border border-border bg-muted text-muted-foreground"><Icon className="size-5" /></div><h3 className="mt-4 text-sm font-semibold">{title}</h3><p className="mt-1 max-w-sm text-xs leading-5 text-muted-foreground">{description}</p></div>; }

function IncidentRows({ events }: { events: Snapshot["events"] }) { return <div>{events.map((event) => <div key={event.id} className="grid gap-3 border-t border-border px-4 py-3 sm:grid-cols-[86px_1fr_120px] sm:items-center"><Severity value={event.severity} /><div className="min-w-0"><div className="truncate text-sm font-medium">{event.summary}</div><div className="mt-0.5 truncate text-xs text-muted-foreground">{event.entity} · {event.evidence[0] ?? "Sem evidência adicional"}</div></div><div className="text-left text-xs text-muted-foreground sm:text-right">{formatDate(event.at)}</div></div>)}</div>; }
function Severity({ value }: { value: string }) { const severe = ["alta", "crítica", "critical"].includes(value.toLowerCase()); return <span className={cn("inline-flex w-fit items-center rounded-sm border px-2 py-1 text-[10px] font-semibold uppercase", severe ? "border-danger/30 bg-danger/10 text-danger" : "border-warning/30 bg-warning/10 text-warning")}>{value}</span>; }

function IncidentList({ events }: { events: Snapshot["events"] }) { return <><PageHeader eyebrow="Operação" title="Incidentes e prioridades" description="Investigue sinais, entidades afetadas e evidências coletadas pelo servidor." actions={<Button variant="outline"><ListFilter /> Filtrar</Button>} /><section className="rounded-lg border border-border bg-surface">{events.length ? <IncidentRows events={events} /> : <EmptyState icon={ShieldCheck} title="Nenhum incidente recebido" description="Os eventos retornados por /api/v1/snapshot serão exibidos aqui." />}</section></>; }

function ServicesPage({ snapshot, filter }: { snapshot: Snapshot; filter: string }) { const nodes = snapshot.service_map.nodes.filter((n) => n.name.toLowerCase().includes(filter.toLowerCase())); return <><PageHeader eyebrow="Aplicações / APM" title="Serviços" description="Serviços descobertos, runtime, instâncias e relações observadas." actions={<Button asChild><Link to="/$" params={{ _splat: "service-mapping" }}><Workflow /> Abrir mapa</Link></Button>} /><div className="overflow-hidden rounded-lg border border-border bg-surface"><DataTable headers={["Serviço", "Tipo", "Runtime / host", "Instâncias", "Estado"]}>{nodes.map((node) => <tr key={node.id} className="border-t border-border"><Cell strong>{node.name}</Cell><Cell>{node.kind}</Cell><Cell>{node.runtime ?? node.host ?? "—"}</Cell><Cell>{node.instances ?? 1}</Cell><Cell><Status value={node.status} /></Cell></tr>)}</DataTable>{!nodes.length && <EmptyState icon={Server} title="Nenhum serviço encontrado" description="A descoberta será exibida quando o snapshot trouxer nós de serviço." />}</div></>; }
function InfrastructurePage({ snapshot, path }: { snapshot: Snapshot; path: string }) { const processes = snapshot.hosts.flatMap((h) => h.processes.map((p) => ({ ...p, host: h.name }))); if (path !== "hosts" && path !== "processos") return <FuturePage title={labels.get(path) ?? "Infraestrutura"} />; return <><PageHeader eyebrow="Infraestrutura" title={path === "hosts" ? "Hosts" : "Processos"} description="Inventário real retornado pelos agentes Linux conectados." /> <div className="overflow-hidden rounded-lg border border-border bg-surface">{path === "hosts" ? <DataTable headers={["Host", "Sistema operacional", "Endereços", "Processos", "Última observação"]}>{snapshot.hosts.map((host) => <tr key={host.id} className="border-t border-border"><Cell strong>{host.name}</Cell><Cell>{host.os}</Cell><Cell>{host.addresses.join(", ") || "—"}</Cell><Cell>{host.processes.length}</Cell><Cell>{formatDate(host.last_seen)}</Cell></tr>)}</DataTable> : <DataTable headers={["PID", "Processo", "Serviço", "Runtime", "Host", "RSS"]}>{processes.map((p) => <tr key={`${p.host}-${p.pid}`} className="border-t border-border"><Cell>{p.pid}</Cell><Cell strong>{p.name}</Cell><Cell>{p.service}</Cell><Cell>{p.runtime}</Cell><Cell>{p.host}</Cell><Cell>{formatBytes(p.rss_bytes)}</Cell></tr>)}</DataTable>}</div></>; }

function DataTable({ headers, children }: { headers: string[]; children: ReactNode }) { return <div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left text-xs"><thead className="bg-muted/40 text-muted-foreground"><tr>{headers.map((header) => <th key={header} className="px-4 py-3 font-medium">{header}</th>)}</tr></thead><tbody>{children}</tbody></table></div>; }
function Cell({ children, strong }: { children: ReactNode; strong?: boolean }) { return <td className={cn("px-4 py-3 text-muted-foreground", strong && "font-medium text-foreground")}>{children}</td>; }
function Status({ value }: { value: string }) { const ok = ["ok", "healthy", "ativo"].includes(value.toLowerCase()); return <span className={cn("inline-flex items-center gap-1.5 text-xs", ok ? "text-success" : "text-warning")}><span className="size-1.5 rounded-full bg-current" />{value}</span>; }

type FlowData = MapNode & Record<string, unknown> & { selected?: boolean };
const TopologyNode = memo(({ data }: NodeProps<Node<FlowData>>) => <div className="min-w-44 rounded-md border border-map-node-border bg-map-node p-3 shadow-map"><Handle type="target" position={Position.Left} className="!bg-primary" /><div className="flex items-center gap-2"><span className={cn("size-2 rounded-full", data.status === "ok" ? "bg-success" : "bg-warning")} /><div className="text-xs font-semibold">{data.name}</div></div><div className="mt-1.5 text-[10px] text-muted-foreground">{data.kind}{data.runtime ? ` · ${data.runtime}` : ""}</div><Handle type="source" position={Position.Right} className="!bg-primary" /></div>);
TopologyNode.displayName = "TopologyNode";

function MappingView({ kind, map, demo }: { kind: "service" | "network"; map: TopologyMap; demo: boolean }) {
  const [selected, setSelected] = useState<MapNode | null>(null);
  const nodes: Node<FlowData>[] = useMemo(() => map.nodes.map((node, index) => ({ id: node.id, type: "topology", position: { x: 80 + (index % 3) * 310, y: 80 + Math.floor(index / 3) * 180 }, data: { ...node } })), [map.nodes]);
  const edges: Edge[] = useMemo(() => map.edges.map((edge) => ({ id: edge.id, source: edge.from, target: edge.to, label: `${edge.kind} · ${edge.count}`, animated: edge.confidence === "observed", style: { strokeWidth: 1.5 }, labelStyle: { fontSize: 10 } })), [map.edges]);
  const selectedEdges = selected ? map.edges.filter((edge) => edge.from === selected.id || edge.to === selected.id) : [];
  return <><PageHeader eyebrow={kind === "service" ? "Aplicações / APM" : "Infraestrutura"} title={kind === "service" ? "Service Mapping" : "Network Mapping"} description={kind === "service" ? "Dependências observadas entre serviços, runtimes e bancos de dados." : "Fluxos IP observados; topologia física SNMP não disponível."} actions={<div className="flex items-center gap-3 rounded-md border border-border bg-surface px-3 py-2 text-xs text-muted-foreground"><span className="size-2 rounded-full bg-success" /> Evidência real {demo && "(amostra demo)"}</div>} />
    <div className="grid min-h-[610px] overflow-hidden rounded-lg border border-border bg-surface lg:grid-cols-[1fr_310px]"><div className="relative min-h-[460px] border-b border-border lg:border-b-0 lg:border-r"><div className="absolute left-3 top-3 z-10 flex gap-2 rounded-md border border-border bg-surface-raised p-2 text-[10px] text-muted-foreground"><span>Confiança: </span><span className="text-success">● alta</span><span className="text-warning">● média</span></div>{map.nodes.length ? <ReactFlow nodes={nodes} edges={edges} nodeTypes={{ topology: TopologyNode }} fitView minZoom={0.3} maxZoom={2} onNodeClick={(_, node) => setSelected(node.data as MapNode)} colorMode="dark"><Background gap={24} size={1} /><Controls /><MiniMap pannable zoomable /></ReactFlow> : <EmptyState icon={Workflow} title="Nenhuma relação observada" description="Quando agentes reportarem processos e conexões, o mapa será construído aqui." />}</div><aside className="p-5">{selected ? <><div className="flex items-start justify-between"><div><div className="text-[10px] font-semibold uppercase text-primary">{selected.kind}</div><h2 className="mt-1 font-semibold">{selected.name}</h2></div><Button variant="ghost" size="icon" className="size-7" onClick={() => setSelected(null)}><X /></Button></div><div className="mt-5 space-y-3 text-xs"><Detail label="Estado" value={selected.status} /><Detail label="Runtime" value={selected.runtime ?? "Não informado"} /><Detail label="Host" value={selected.host ?? "Não informado"} /><Detail label="Instâncias" value={String(selected.instances ?? 1)} /></div><div className="mt-6 border-t border-border pt-5"><h3 className="text-xs font-semibold">Evidências relacionadas</h3>{selectedEdges.length ? selectedEdges.map((edge) => <div key={edge.id} className="mt-3 rounded-md border border-border bg-muted/30 p-3"><div className="text-xs font-medium">{edge.kind} · {edge.count} observações</div><p className="mt-1 text-[11px] leading-5 text-muted-foreground">{edge.evidence}</p><div className="mt-2 text-[10px] text-primary">Confiança {edge.confidence}</div></div>) : <p className="mt-2 text-xs text-muted-foreground">Nenhuma aresta relacionada.</p>}</div></> : <EmptyState icon={PanelRight} title="Selecione um nó" description="Veja runtime, host, relações, evidência e confiança." />}</aside></div>
  </>;
}

function Detail({ label, value }: { label: string; value: string }) { return <div className="flex justify-between gap-3 border-b border-border pb-2"><span className="text-muted-foreground">{label}</span><span className="text-right font-medium">{value}</span></div>; }

function TemplateEditor({ items, demo }: { items: MonitorTemplate[]; demo: boolean }) {
  const queryClient = useQueryClient(); const [open, setOpen] = useState(false);
  const create = useMutation({ mutationFn: api.createTemplate, onSuccess: () => { toast.success("Template criado no servidor"); setOpen(false); void queryClient.invalidateQueries({ queryKey: ["snapshot"] }); }, onError: (error) => toast.error(error.message) });
  const remove = useMutation({ mutationFn: api.deleteTemplate, onSuccess: () => { toast.success("Template removido"); void queryClient.invalidateQueries({ queryKey: ["snapshot"] }); }, onError: (error) => toast.error(error.message) });
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (demo) { toast.info("A gravação não está disponível no modo demonstração"); return; } const data = new FormData(event.currentTarget); create.mutate({ id: crypto.randomUUID(), name: String(data.get("name")), kind: String(data.get("kind")) as "http" | "tcp", target: String(data.get("target")), interval_seconds: 60, timeout_seconds: 5, expected_status: Number(data.get("status") || 200), enabled: true, last_run: "", last_value: 0, last_error: "", status: "pendente" }); }
  return <><PageHeader eyebrow="Monitoramento" title="Templates" description="Receitas HTTP e TCP compatíveis com o backend Observa Lite." actions={<Button onClick={() => setOpen(true)}><Plus /> Novo template</Button>} /><div className="overflow-hidden rounded-lg border border-border bg-surface"><DataTable headers={["Nome", "Tipo", "Destino", "Intervalo", "Resultado", "Estado", ""]}>{items.map((item) => <tr key={item.id} className="border-t border-border"><Cell strong>{item.name}</Cell><Cell>{item.kind.toUpperCase()}</Cell><Cell>{item.target}</Cell><Cell>{item.interval_seconds}s</Cell><Cell>{item.last_value || "Ainda não executado"}</Cell><Cell><Status value={item.status} /></Cell><Cell><Button variant="ghost" size="icon" disabled={demo} onClick={() => { if (window.confirm(`Remover ${item.name}?`)) remove.mutate(item.id); }} aria-label="Excluir template"><Trash2 /></Button></Cell></tr>)}</DataTable>{!items.length && <EmptyState icon={ListFilter} title="Nenhum template" description="Crie um monitor HTTP ou TCP para começar." />}</div><EditorDialog open={open} setOpen={setOpen} title="Novo template" description="O objeto será enviado para POST /api/v1/templates."><form onSubmit={submit} className="space-y-4"><Field name="name" label="Nome" placeholder="Saúde da API" /><Field name="target" label="Destino" placeholder="https://api.exemplo/health ou host:porta" /><div className="grid grid-cols-2 gap-3"><SelectField name="kind" label="Tipo" options={["http", "tcp"]} /><Field name="status" label="Status esperado" placeholder="200" type="number" /></div><Button className="w-full" disabled={create.isPending}>{create.isPending ? "Salvando..." : "Salvar no servidor"}</Button></form></EditorDialog></>;
}

function DataSourceEditor({ items, demo }: { items: DataSource[]; demo: boolean }) {
  const queryClient = useQueryClient(); const [open, setOpen] = useState(false);
  const create = useMutation({ mutationFn: api.createDataSource, onSuccess: () => { toast.success("Fonte registrada no servidor"); setOpen(false); void queryClient.invalidateQueries({ queryKey: ["snapshot"] }); }, onError: (error) => toast.error(error.message) });
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (demo) { toast.info("A gravação não está disponível no modo demonstração"); return; } const data = new FormData(event.currentTarget); create.mutate({ id: crypto.randomUUID(), name: String(data.get("name")), kind: String(data.get("kind")) as "prometheus" | "json", url: String(data.get("url")), secret_env: String(data.get("secret_env")) || undefined }); }
  return <><PageHeader eyebrow="Explorar" title="Data Sources" description="Fontes Prometheus e JSON configuradas no backend. Segredos permanecem no servidor por variável de ambiente." actions={<Button onClick={() => setOpen(true)}><Plus /> Nova fonte</Button>} /><div className="grid gap-3 lg:grid-cols-2">{items.map((item) => <div key={item.id} className="rounded-lg border border-border bg-surface p-5"><div className="flex items-start justify-between"><div className="flex gap-3"><div className="grid size-9 place-items-center rounded bg-muted"><Database className="size-4 text-primary" /></div><div><h2 className="text-sm font-semibold">{item.name}</h2><p className="mt-0.5 text-xs uppercase text-muted-foreground">{item.kind}</p></div></div><span className="rounded-sm border border-success/30 bg-success/10 px-2 py-1 text-[10px] text-success">CONFIGURADA</span></div><p className="mt-5 truncate font-mono text-xs text-muted-foreground">{item.url}</p><div className="mt-4 border-t border-border pt-3 text-xs text-muted-foreground">Credencial: {item.secret_env ? `variável ${item.secret_env}` : "não informada"}</div></div>)}{!items.length && <div className="lg:col-span-2"><EmptyState icon={Database} title="Nenhuma fonte configurada" description="Adicione uma fonte Prometheus ou JSON suportada pelo backend." /></div>}</div><EditorDialog open={open} setOpen={setOpen} title="Nova fonte de dados" description="Não insira segredos. Informe somente o nome da variável existente no servidor."><form onSubmit={submit} className="space-y-4"><Field name="name" label="Nome" placeholder="Prometheus principal" /><SelectField name="kind" label="Tipo" options={["prometheus", "json"]} /><Field name="url" label="URL" placeholder="http://prometheus:9090" /><Field name="secret_env" label="Variável de segredo (opcional)" placeholder="PROMETHEUS_TOKEN" /><Button className="w-full" disabled={create.isPending}>Salvar no servidor</Button></form></EditorDialog></>;
}

function DashboardBuilder({ items, demo }: { items: Dashboard[]; demo: boolean }) {
  const queryClient = useQueryClient(); const [open, setOpen] = useState(false);
  const create = useMutation({ mutationFn: api.createDashboard, onSuccess: () => { toast.success("Dashboard salvo"); setOpen(false); void queryClient.invalidateQueries({ queryKey: ["snapshot"] }); }, onError: (error) => toast.error(error.message) });
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (demo) { toast.info("A gravação não está disponível no modo demonstração"); return; } const data = new FormData(event.currentTarget); create.mutate({ id: crypto.randomUUID(), title: String(data.get("title")), panels: [{ id: crypto.randomUUID(), title: String(data.get("panelTitle")), kind: String(data.get("kind")), html: String(data.get("html")) || undefined, query: String(data.get("query")) || undefined }] }); }
  return <><PageHeader eyebrow="Visualização" title="Dashboards" description="Painéis salvos pelo backend, incluindo estatísticas e HTML isolado em sandbox." actions={<Button onClick={() => setOpen(true)}><Plus /> Novo dashboard</Button>} />{items.length ? <div className="grid gap-4 xl:grid-cols-2">{items.map((dashboard) => <section key={dashboard.id} className="rounded-lg border border-border bg-surface p-4"><h2 className="text-sm font-semibold">{dashboard.title}</h2><div className="mt-4 grid gap-3 sm:grid-cols-2">{dashboard.panels.map((panel) => <div key={panel.id} className="min-h-36 rounded-md border border-border bg-surface-raised p-3"><div className="text-xs font-medium text-muted-foreground">{panel.title}</div>{panel.kind === "html" && panel.html ? <iframe title={panel.title} sandbox="" srcDoc={`<style>${panel.css ?? ""}</style>${panel.html}`} className="mt-3 h-28 w-full border-0 bg-transparent" /> : <div className="mt-7 text-center text-3xl font-semibold text-primary">{panel.query ?? "—"}</div>}</div>)}</div></section>)}</div> : <EmptyState icon={LayoutDashboard} title="Nenhum dashboard" description="Crie um dashboard e salve a definição no backend." />}<EditorDialog open={open} setOpen={setOpen} title="Novo dashboard" description="Crie um primeiro painel stat ou HTML."><form onSubmit={submit} className="space-y-4"><Field name="title" label="Título do dashboard" placeholder="Operação Linux" /><Field name="panelTitle" label="Título do painel" placeholder="Disponibilidade" /><SelectField name="kind" label="Tipo" options={["stat", "html"]} /><Field name="query" label="Consulta ou valor" placeholder={'up{job="api"}'} /><div><Label htmlFor="html">HTML (opcional)</Label><Textarea id="html" name="html" className="mt-2 min-h-28 font-mono text-xs" placeholder="<strong>Estado operacional</strong>" /></div><Button className="w-full" disabled={create.isPending}>Salvar no servidor</Button></form></EditorDialog></>;
}

function ExtensionHub({ configuredOnly }: { configuredOnly: boolean }) {
  const [search, setSearch] = useState(""); const [category, setCategory] = useState<"Todos" | ExtensionCategory>("Todos"); const [selected, setSelected] = useState<ExtensionManifest | null>(null);
  const filtered = extensionManifest.filter((item) => (!configuredOnly || false) && (category === "Todos" || item.category === category) && item.name.toLowerCase().includes(search.toLowerCase()));
  return <><PageHeader eyebrow="Extensões" title={configuredOnly ? "Minhas extensões" : "Hub de Extensões"} description={configuredOnly ? "Conexões realmente configuradas aparecerão aqui quando o backend fornecer esse estado." : "Catálogo planejado de integrações. Catálogo não significa instalado, ativo ou funcional."} />{configuredOnly ? <EmptyState icon={Boxes} title="Nenhuma conexão confirmada pelo backend" description="Esta interface não presume extensões instaladas. Consulte o Hub para ver o catálogo planejado." /> : <><div className="mb-5 flex flex-col gap-3 rounded-lg border border-border bg-surface p-4"><div className="relative max-w-xl"><Search className="absolute left-3 top-2.5 size-4 text-muted-foreground" /><Input value={search} onChange={(event) => setSearch(event.target.value)} className="pl-9" placeholder="Pesquisar extensões e integrações" /></div><div className="flex flex-wrap gap-2">{(["Todos", "APM", "Cloud", "Banco de dados", "Rede", "Integrações", "Observabilidade", "IA"] as const).map((value) => <Button key={value} variant={category === value ? "default" : "outline"} size="sm" onClick={() => setCategory(value)}>{value}</Button>)}</div></div><div className="grid gap-3 md:grid-cols-2 2xl:grid-cols-3">{filtered.map((item) => <button key={item.id} onClick={() => setSelected(item)} className="group rounded-lg border border-border bg-surface p-4 text-left transition-colors hover:border-primary/50 hover:bg-surface-raised"><div className="flex items-start gap-3"><div className="grid size-10 shrink-0 place-items-center rounded-md border border-border bg-muted text-primary"><item.icon className="size-5" /></div><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><h2 className="font-semibold">{item.name}</h2><span className={cn("rounded-sm border px-1.5 py-0.5 text-[9px] uppercase", item.status === "Catálogo" ? "border-primary/30 text-primary" : "border-border text-muted-foreground")}>{item.status}</span></div><p className="mt-1 line-clamp-2 text-xs leading-5 text-muted-foreground">{item.description}</p></div></div><div className="mt-4 flex items-center justify-between border-t border-border pt-3 text-[10px] text-muted-foreground"><span>{item.category} · {item.type}</span><span>{item.version}</span></div></button>)}</div></>}<ExtensionDetail item={selected} onClose={() => setSelected(null)} /></>;
}

function ExtensionDetail({ item, onClose }: { item: ExtensionManifest | null; onClose: () => void }) { return <Sheet open={Boolean(item)} onOpenChange={(open) => !open && onClose()}><SheetContent className="w-full border-border bg-surface sm:max-w-lg">{item && <><SheetHeader><div className="mb-4 grid size-12 place-items-center rounded-md border border-border bg-muted text-primary"><item.icon /></div><SheetTitle>{item.name}</SheetTitle><SheetDescription>{item.description}</SheetDescription></SheetHeader><div className="mt-7 space-y-3 text-sm"><Detail label="Autor" value={item.author} /><Detail label="Compatibilidade" value={item.compatibility} /><Detail label="Tipo" value={item.type} /><Detail label="Versão" value={item.version} /><Detail label="Estado" value={item.status} /></div><div className="mt-7 rounded-md border border-warning/30 bg-warning/10 p-4"><div className="text-sm font-semibold text-warning">Disponível em versões futuras</div><p className="mt-1 text-xs leading-5 text-muted-foreground">Configurar e ativar só estarão disponíveis quando o backend publicar suporte e estado de conexão.</p></div><Button className="mt-5 w-full" disabled>Configurar</Button></>}</SheetContent></Sheet>; }

function AuthSettings({ section }: { section: string }) { return <><PageHeader eyebrow="Administração" title={section === "usuarios-acesso" ? "Usuários & acesso" : section === "autenticacao" ? "Autenticação (SSO/MFA)" : "Chaves de API"} description="Estado honesto dos recursos de segurança disponíveis nesta versão." /><div className="mb-5 flex items-center gap-3 rounded-lg border border-warning/30 bg-warning/10 p-4"><KeyRound className="size-5 text-warning" /><div><div className="text-sm font-semibold">Acesso por token (modo inicial)</div><p className="mt-0.5 text-xs text-muted-foreground">O backend atual usa um token administrativo. Usuários, sessões, RBAC, OIDC e MFA não são aplicados pelo servidor.</p></div></div><Tabs defaultValue="acesso"><TabsList><TabsTrigger value="acesso">Acesso atual</TabsTrigger><TabsTrigger value="oidc">OIDC / SSO</TabsTrigger><TabsTrigger value="roles">Perfis e roles</TabsTrigger></TabsList><TabsContent value="acesso"><SecurityCard icon={KeyRound} title="Token administrativo" status="Em uso" description="Mantido somente em sessionStorage nesta aba. Não há persistência longa." /></TabsContent><TabsContent value="oidc"><div className="grid gap-4 lg:grid-cols-2"><SecurityCard icon={ShieldCheck} title="SSO via OIDC" status="Não configurado nesta versão" description="Preparado para Keycloak, Authentik ou Azure Entra. Requer implementação no backend antes da ativação." /><SecurityCard icon={LockKeyhole} title="MFA" status="Não configurado nesta versão" description="A exigência deverá ser aplicada no provedor de identidade, nunca simulada apenas na interface." /></div><div className="mt-4 rounded-lg border border-border bg-surface p-5"><h3 className="text-sm font-semibold">Parâmetros previstos para OIDC</h3><div className="mt-4 grid gap-4 md:grid-cols-2"><Field name="issuer" label="Issuer URL" placeholder="https://idp.exemplo/realms/observa" disabled /><Field name="client" label="Client ID" placeholder="observa-lite" disabled /><Field name="callback" label="Callback URL" placeholder="https://observa.exemplo/auth/callback" disabled /><Field name="mfa" label="Política MFA no IdP" placeholder="Obrigatória para administradores" disabled /></div><p className="mt-4 text-xs text-muted-foreground">Segredos de cliente não devem ser enviados ao navegador. Configure-os somente no backend quando houver suporte.</p></div></TabsContent><TabsContent value="roles"><SecurityCard icon={Users} title="RBAC" status="Não configurado nesta versão" description="Perfis, permissões e auditoria dependerão da validação efetiva no backend." /></TabsContent></Tabs></>; }
function SecurityCard({ icon: Icon, title, status, description }: { icon: LucideIcon; title: string; status: string; description: string }) { return <div className="rounded-lg border border-border bg-surface p-5"><div className="flex items-start justify-between gap-3"><div className="grid size-9 place-items-center rounded bg-muted"><Icon className="size-4 text-primary" /></div><span className={cn("rounded-sm border px-2 py-1 text-[10px]", status === "Em uso" ? "border-success/30 bg-success/10 text-success" : "border-border text-muted-foreground")}>{status}</span></div><h2 className="mt-4 text-sm font-semibold">{title}</h2><p className="mt-1 text-xs leading-5 text-muted-foreground">{description}</p><Button className="mt-4" variant="outline" disabled={status !== "Em uso"}>Configurar</Button></div>; }

function FuturePage({ title }: { title: string }) { return <><PageHeader eyebrow="Observa Lite" title={title} description="Esta área está preparada para receber telemetria e recursos quando o backend publicar suporte." /><div className="rounded-lg border border-border bg-surface"><EmptyState icon={LifeBuoy} title="Sem dados disponíveis" description="Nenhuma capacidade é simulada. Conecte a integração ou aguarde o suporte desta versão do servidor." /></div></>; }

function EditorDialog({ open, setOpen, title, description, children }: { open: boolean; setOpen: (open: boolean) => void; title: string; description: string; children: ReactNode }) { return <Dialog open={open} onOpenChange={setOpen}><DialogContent className="border-border bg-surface"><DialogHeader><DialogTitle>{title}</DialogTitle><DialogDescription>{description}</DialogDescription></DialogHeader>{children}</DialogContent></Dialog>; }
function Field({ name, label, placeholder, type = "text", disabled = false }: { name: string; label: string; placeholder: string; type?: string; disabled?: boolean }) { return <div><Label htmlFor={name}>{label}</Label><Input id={name} name={name} type={type} placeholder={placeholder} disabled={disabled} className="mt-2" required={!disabled} /></div>; }
function SelectField({ name, label, options }: { name: string; label: string; options: string[] }) { return <div><Label>{label}</Label><Select name={name} defaultValue={options[0]}><SelectTrigger className="mt-2"><SelectValue /></SelectTrigger><SelectContent>{options.map((option) => <SelectItem key={option} value={option}>{option.toUpperCase()}</SelectItem>)}</SelectContent></Select></div>; }
function formatDate(value: string) { if (!value) return "—"; return new Intl.DateTimeFormat("pt-BR", { dateStyle: "short", timeStyle: "short" }).format(new Date(value)); }
function formatBytes(value: number) { return new Intl.NumberFormat("pt-BR", { style: "unit", unit: "megabyte", maximumFractionDigits: 0 }).format(value / 1_048_576); }